import { beforeEach, describe, expect, it } from 'vitest'
import { defaultProjectData, type ProjectData } from '#/lib/project'
import { openDatabase } from '../db.server'
import { createProjectStore, type ProjectStore } from '../projects.server'
import { handleAgentRequest } from './agentInterface.server'

let store: ProjectStore
let time: number
let nextId = 1
const advance = (ms: number) => {
  time += ms
}

beforeEach(() => {
  time = Date.parse('2026-01-01T10:00:00.000Z')
  store = createProjectStore(openDatabase(':memory:'), { now: () => new Date(time) })
})

const withGrammar = (grammar: string): ProjectData => {
  const data = defaultProjectData()
  return { ...data, ll: { ...data.ll, grammar } }
}

function post(body: unknown, headers: Record<string, string> = {}) {
  return handleAgentRequest(
    new Request('http://localhost:3000/mcp', {
      method: 'POST',
      headers: { 'content-type': 'application/json', accept: 'application/json, text/event-stream', ...headers },
      body: JSON.stringify(body),
    }),
    store,
  )
}

async function rpc(method: string, params?: unknown) {
  const res = await post({ jsonrpc: '2.0', id: nextId++, method, params })
  expect(res.status).toBe(200)
  return (await res.json()) as { result?: any; error?: { code: number; message: string } }
}

/** Calls a tool; a successful result is its JSON, a tool error is { error: message }. */
async function call(name: string, args: Record<string, unknown> = {}) {
  const { result, error } = await rpc('tools/call', { name, arguments: args })
  if (error) return { protocolError: error.message }
  const text = result.content[0].text as string
  return result.isError ? { error: text } : JSON.parse(text)
}

