describe('discovering tools', () => {
  it('tools/list offers the read tools, each with an agent-facing description and an argument schema', async () => {
    const { result } = await rpc('tools/list')
    const tools = result.tools as { name: string; description: string; inputSchema: any; annotations: any }[]

    expect(tools.map((t) => t.name)).toEqual([
      'list_projects',
      'list_snapshots',
      'get_part',
      'get_project_settings',
      'get_ll_table',
      'get_sets',
      'get_prec_table',
      'get_problems',
      'export',
      'simulate_ll',
      'simulate_prec',
    ])
    for (const tool of tools) {
      expect(tool.description.length).toBeGreaterThan(40)
      expect(tool.inputSchema.type).toBe('object')
      expect(tool.annotations.readOnlyHint).toBe(true)
    }

    const getPart = tools.find((t) => t.name === 'get_part')!
    expect(getPart.inputSchema.required).toEqual(['target', 'part'])
    expect(getPart.inputSchema.properties.part.enum).toEqual(['definition', 'grammarRules', 'precTable', 'reductionRules'])
    expect(getPart.inputSchema.properties.target.properties.kind.enum).toEqual(['project', 'snapshot'])
    const exportTool = tools.find((t) => t.name === 'export')!
    expect(exportTool.inputSchema.properties.kind.enum).not.toContain('ll-png')
  })
})

describe('stateless transport', () => {
  it.each(['GET', 'DELETE'])('%s (server-sent event stream / session end) is not offered: 405 with Allow: POST', async (method) => {
    const res = await handleAgentRequest(new Request('http://localhost:3000/mcp', { method, headers: { accept: 'text/event-stream' } }), store)
    expect(res.status).toBe(405)
    expect(res.headers.get('allow')).toBe('POST')
  })
})

describe('browser requests', () => {
  const ping = { jsonrpc: '2.0', id: 1, method: 'ping' }

  it.each(['cross-site', 'same-site'])('a web page on another site (Sec-Fetch-Site: %s) is refused', async (site) => {
    const res = await post(ping, { 'sec-fetch-site': site })
    expect(res.status).toBe(403)
  })

  it.each(['same-origin', 'none'])('a request from the app itself or typed by the user (Sec-Fetch-Site: %s) is served', async (site) => {
    const res = await post(ping, { 'sec-fetch-site': site })
    expect(res.status).toBe(200)
  })

  it('an old browser without Fetch Metadata posting from another origin is refused', async () => {
    const res = await post(ping, { origin: 'http://evil.example' })
    expect(res.status).toBe(403)
  })

  it('an agent or curl sending no Fetch Metadata is served', async () => {
    expect((await post(ping)).status).toBe(200)
  })
})

