describe('simulations', () => {
  // E → id | id + E rewritten without the conflict, plus a full precedence table for id and +.
  const parsable = (): ProjectData => ({
    ...expressions(),
    def: { nonterminals: 'E\nR', terminals: 'id +', start: 'E' },
    ll: { grammar: 'E -> id R\nR -> + id R\nR -> eps', input: 'id' },
    prec: {
      terminals: ['+', 'id'],
      cells: { '$\u0001id': '<', '$\u0001+': '<', 'id\u0001+': '>', 'id\u0001$': '>', '+\u0001id': '<', '+\u0001+': '>', '+\u0001$': '>' },
      rules: 'E -> E + E\nE -> id',
      input: 'id',
    },
  })

  it('an agent runs the LL simulation on an input of its choice and gets the full trace and the left parse', async () => {
    const p = store.createProject('Výrazy', parsable())
    const res = await call('simulate_ll', { target: { kind: 'project', id: p.id }, input: 'id + id' })

    expect(res.target).toEqual({ kind: 'project', id: p.id, projectId: p.id, revision: 1 })
    expect(res.input).toBe('id + id')
    expect(res.ok).toBe(true)
    expect(res.leftParse).toEqual([1, 2, 3])
    expect(res.steps[0]).toEqual({ stack: '$ E', input: 'id + id $', kind: 'expand', action: '1: E → id R', rule: 1, cell: { nonterminal: 'E', terminal: 'id' } })
    expect(res.steps.at(-1)).toMatchObject({ stack: '$', input: '$', kind: 'accept' })
    expect(res.steps.map((s: { kind: string }) => s.kind)).toEqual(['expand', 'match', 'expand', 'match', 'match', 'expand', 'accept'])
  })

  it('an agent runs the precedence simulation on an input of its choice and gets the full trace', async () => {
    const p = store.createProject('Výrazy', parsable())
    const res = await call('simulate_prec', { target: { kind: 'project', id: p.id }, input: 'id + id' })

    expect(res.ok).toBe(true)
    expect(res.steps[0]).toEqual({ stack: '$', relation: '<', input: 'id + id $', rule: '' })
    expect(res.steps.length).toBeGreaterThan(4)
    expect(res.steps.some((s: { rule: string }) => s.rule.includes('id'))).toBe(true)
  })

  it('simulations never change the revision or the saved simulation inputs', async () => {
    const p = store.createProject('Výrazy', parsable())
    await call('simulate_ll', { target: { kind: 'project', id: p.id }, input: 'id + id' })
    await call('simulate_prec', { target: { kind: 'project', id: p.id }, input: 'id + + id' })

    const after = store.getProject(p.id)!
    expect(after.revision).toBe(1)
    expect(after.data.ll.input).toBe('id')
    expect(after.data.prec.input).toBe('id')
  })

  it('an input that does not parse gives a failed trace, not a tool error', async () => {
    const p = store.createProject('Výrazy', parsable())
    const res = await call('simulate_ll', { target: { kind: 'project', id: p.id }, input: 'id id' })
    expect(res.ok).toBe(false)
    expect(res.message).toEqual(expect.any(String))
  })

  it('simulating a target without grammar rules or with an empty input gives a tool error', async () => {
    const p = store.createProject('Prázdny', defaultProjectData())
    expect((await call('simulate_ll', { target: { kind: 'project', id: p.id }, input: 'id' })).error).toMatch(/grammar rules/)
    expect((await call('simulate_prec', { target: { kind: 'project', id: p.id }, input: 'id' })).error).toMatch(/reduction rules/)
    const q = store.createProject('Výrazy', parsable())
    expect((await call('simulate_ll', { target: { kind: 'project', id: q.id }, input: '  ' })).error).toMatch(/input/)
  })
})
